use serde_json::Value;use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf}};
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-packed-tree176";
fn walk(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),v)}else{v.push(e.path());}}}
fn main(){let path=format!("{D}/README.md");let mut s=fs::read_to_string(&path).unwrap();for(a,b)in[("CPU 2 /CPUs 0–15 /CPUs 0–31 for1/16/ 32 workers","CPU 2, CPUs 0–15 or CPUs 0–31 for 1/16/32 workers"),("Curve/ 32-worker","Curve / 32-worker"),("OFF/original:1.025468822 [1.019061541,1.032135248]","OFF/original: 1.025468822 [1.019061541, 1.032135248]"),("31/ 32/33","31/32/33"),("and1/4/16/ 32-worker512KiB","and 1/4/16/32-worker 512 KiB"),("No successful capture, test or profile is repeated.","No native test suite or timed capture is repeated.")]{s=s.replace(a,b);}fs::write(&path,&s).unwrap();let m:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json").unwrap()).unwrap();let rows=s.lines().filter(|l|l.starts_with('|')&&l.matches('×').count()==2).collect::<Vec<_>>();assert_eq!(rows.len(),8);for row in rows{let c=row.split('|').collect::<Vec<_>>();let r=&m["m5"][c[1]];assert!((c[2].parse::<f64>().unwrap()-r["accepted_ms"].as_f64().unwrap()).abs()<1e-9);assert_eq!(c[3].parse::<f64>().unwrap(),r["cpu_reference_ms"].as_f64().unwrap());assert_eq!(c[5].parse::<f64>().unwrap(),r["metal_reference_ms"].as_f64().unwrap());assert_eq!(r["goal10x"],false);}let mut rest=s.as_str();let mut links=0;let mut external=0;while let Some(i)=rest.find("]("){rest=&rest[i+2..];let j=rest.find(')').unwrap();let link=&rest[..j];if link.starts_with("https://"){assert_eq!(link,"https://arxiv.org/abs/2608.13948v2");external+=1;}else{assert!(Path::new(D).join(link).is_file(),"{link}");links+=1;}rest=&rest[j+1..];}assert_eq!((links,external),(15,1));fs::copy(file!(),format!("{D}/artifacts/final-review.rs")).unwrap();let mut all=vec![];walk(Path::new(D),&mut all);all.sort();let mut sums=String::new();for f in all{let rel=f.strip_prefix(D).unwrap();if rel==Path::new("SHA256SUMS"){continue;}sums.push_str(&format!("{:x}  {}\n",Sha256::digest(fs::read(&f).unwrap()),rel.display()));}fs::write(format!("{D}/SHA256SUMS"),sums).unwrap();println!("Prose-onlyspacing;all8acceptedCPU/Metalrows+15locallinks+1paperlinkPASS;checksumsclosed");}
